insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('01f4b4c4-4dc7-4cb1-a589-5b195861c4de', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$inleiding: monopolist Solo overweegt over te stappen van diesel op biobrandstof$$,
   $$economie-vwo-2026-i-solo-context1.png$$,
   $$Monopolist Solo is een rederij die personen vervoert per boot tussen verschillende Indonesische eilanden. De directeur overweegt vanwege het milieu de vervuilende diesel te vervangen door een schonere, duurdere biobrandstof. In figuur 1 zijn de kosten en opbrengsten van Solo geschetst.$$, 'inline'),
  ('d8784f47-8066-4499-8347-7f7e3624d2f1', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$figuur 1: kosten en opbrengsten van Solo in 2025$$,
   $$economie-vwo-2026-i-solo-context2.png$$,
   $$Figuur 1 Kosten en opbrengsten van Solo in 2025
verticale as: prijs in roepia (× 1.000); horizontale as: Q (aantal tickets).
Twee dalende lijnen vanuit hetzelfde punt op de verticale as: een steilere (niet gelabelde) lijn en GO; horizontale lijnen MKbio (hoger) en MKdiesel (lager); gestippelde hulplijnen bij de twee snijpunten van de steilere lijn met MKdiesel en MKbio.
GO = −2Q + 100
MKdiesel = 16 (x 1.000)
MKbio = 24 (x 1.000)
GO is de prijs van een ticket in roepia (x 1.000)$$, 'inline'),
  ('6f3f6bf7-e01c-463a-be85-6c1be05d09c1', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$winstmaximalisatie bij diesel: prijs 58.000 roepia, winst 690.000 roepia$$,
   $$economie-vwo-2026-i-solo-context3.png$$,
   $$Solo streeft naar maximale winst en behaalt deze bij het gebruik van diesel bij een prijs van 58.000 roepia per ticket. De winst is dan 690.000 roepia.$$, 'inline'),
  ('db8fce4e-9e08-4b4d-9a29-4299b594d746', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$keuze voor biobrandstof vanwege sociale normen; hogere marginale kosten$$,
   $$economie-vwo-2026-i-solo-context4.png$$,
   $$De directeur kiest vanwege sociale normen voor biobrandstof. De stijging van de marginale kosten leidt tot een nieuwe prijs. Solo streeft nog steeds naar maximale winst.$$, 'inline'),
  ('94ac5e7e-cd35-4854-aaed-f748012f0d6f', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$verandering totale surplus bij winstmaximalisatie$$,
   $$economie-vwo-2026-i-solo-context5.png$$,
   $$Als gevolg van de keuze voor biobrandstof verandert het totale surplus bij winstmaximalisatie.$$, 'inline'),
  ('04076b13-fec2-4ac5-bcf3-3b6ba6f98d44', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$rederij Laman treedt toe met drie strategieën$$,
   $$economie-vwo-2026-i-solo-context6.png$$,
   $$Rederij Laman ziet winstkansen en zal in 2026 toetreden door te varen met biobrandstof. Laman heeft drie strategieën om toe te treden tot de markt (zie spelboom 1). Vanwege deze concurrentie verwacht Solo minder winst te behalen en overweegt weer op diesel te gaan varen.$$, 'inline'),
  ('2b040903-eb53-40fc-8461-7753b704ed90', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$spelboom 1: winsten in roepia (x 1.000) in 2026$$,
   $$economie-vwo-2026-i-solo-context7.png$$,
   $$Spelboom 1 Winsten in roepia (x 1.000) in het jaar 2026
Laman kiest eerst (lager tarief, snellere boot of meer vaartijden), daarna kiest Solo (bio of diesel).
lager tarief – bio: 160 ; 200 | diesel: 80 ; 210
snellere boot – bio: 240 ; 80 | diesel: 120 ; 160
meer vaartijden – bio: 80 ; 100 | diesel: 60 ; 120
(eerste getal: Laman; tweede, vetgedrukte getal: Solo)$$, 'inline'),
  ('3833da54-75b3-42a1-a775-8eb85ffa41fa', 'ad5a2f2a-07d4-411b-8b4f-c12c4e102709', $$winst Solo daalt in 2027 als gevolg van speluitkomst 2026$$,
   $$economie-vwo-2026-i-solo-context8.png$$,
   $$De winst van Solo zal in 2027 dalen als gevolg van de speluitkomst in 2026.$$, 'inline'),
  ('afad2a4d-d82a-488d-9378-1fbaa169fca0', 'e2426d92-4181-49da-83e5-b7ac65723519', $$in deze opgave gaat het bij de rente altijd om de geldmarktrente$$,
   $$economie-vwo-2026-i-geld-in-de-markt-context1.png$$,
   $$In deze opgave gaat het bij de rente altijd om de geldmarktrente.$$, 'inline'),
  ('419c3bf7-2aaf-47df-a858-780de75a93a7', 'e2426d92-4181-49da-83e5-b7ac65723519', $$geldmarkt: aanbieders en vragers van kortlopende leningen$$,
   $$economie-vwo-2026-i-geld-in-de-markt-context2.png$$,
   $$De geldmarktrente is de rente op kortlopende leningen. Op de geldmarkt bieden pensioenfondsen en banken geld aan. Overheden vragen om geld als zij kortlopende leningen afsluiten om investeringen in publiek kapitaal te financieren. Ook gezinnen zijn vragers op de geldmarkt.$$, 'inline'),
  ('91684a3c-4224-4418-8625-98a24b07b0df', 'e2426d92-4181-49da-83e5-b7ac65723519', $$centrale bank heeft invloed op de geldmarktrente; model van een econoom$$,
   $$economie-vwo-2026-i-geld-in-de-markt-context3.png$$,
   $$Ook de centrale bank heeft invloed op de geldmarktrente. Een econoom maakt een model van de geldmarkt (zie figuur 2) en analyseert de gevolgen van het ingrijpen van de centrale bank.$$, 'inline'),
  ('dd5832f1-7204-4394-a4ce-db7438d5d367', 'e2426d92-4181-49da-83e5-b7ac65723519', $$figuur 2: geldmarkt, met legenda$$,
   $$economie-vwo-2026-i-geld-in-de-markt-context4.png$$,
   $$Figuur 2 Geldmarkt
verticale as: nominale rente in % (−1 tot 7); horizontale as: geldhoeveelheid in miljarden $ (0 tot 70).
A₀: horizontaal bij −0,5% tot 10, daarna stijgend tot 7% bij 60.
A₁ (gestippeld): horizontaal bij −0,5% tot 30, daarna stijgend tot ongeveer 5,5% bij 70.
V: dalend van 7% bij 20 naar −0,5% bij 70; snijdt A₀ bij 4% en 40, en A₁ bij 2,5% en 50.
A₀ = aanbod voordat de centrale bank ingrijpt
A₁ = aanbod nadat de centrale bank ingrijpt
V = vraag naar geld$$, 'inline'),
  ('a624d6df-c0fb-4672-87ae-b20f010a1189', 'e2426d92-4181-49da-83e5-b7ac65723519', $$lagere rente verlaagt de rente-inkomsten op opgebouwd vermogen$$,
   $$economie-vwo-2026-i-geld-in-de-markt-context5.png$$,
   $$Door de lagere rente na het ingrijpen van de centrale bank dalen de rente-inkomsten op opgebouwd vermogen door gezinnen.$$, 'inline'),
  ('6eec2d56-a6c6-43fd-88f2-e348832c9d80', 'e2426d92-4181-49da-83e5-b7ac65723519', $$rente-elasticiteit als maat voor effectiviteit monetair beleid$$,
   $$economie-vwo-2026-i-geld-in-de-markt-context6.png$$,
   $$De effectiviteit van het monetaire beleid kan worden gemeten door de rente-elasticiteit. De rente-elasticiteit meet hoe sterk de vraag naar geld reageert als gevolg van een renteverandering.$$, 'inline'),
  ('ed14aedd-20ff-42fa-950f-fc81a9b272ab', 'e2426d92-4181-49da-83e5-b7ac65723519', $$effectieve ondergrens nominale rente is −0,5%$$,
   $$economie-vwo-2026-i-geld-in-de-markt-context7.png$$,
   $$Uit onderzoek blijkt dat de effectieve ondergrens van de nominale rente geen 0%, maar −0,5% is. Ondanks deze negatieve nominale rente kunnen consumenten toch besluiten hun spaargeld bij een bank aan te houden.$$, 'inline'),
  ('9c200ae6-be8b-4536-9671-e74f18777c03', 'ae91f8c2-33c3-4cce-a7ba-7205d735b4c3', $$hervorming inkomstenbelasting: progressief stelsel vervangen door vlaktaks$$,
   $$economie-vwo-2026-i-beleid-context1.png$$,
   $$In 2026 heeft een land het stelsel van inkomstenbelasting hervormd. Hierbij is het progressieve stelsel vervangen door een vlaktaks zonder heffingskortingen. Het tarief van deze vlaktaks is gelijk aan het gemiddelde landelijke tarief in 2025.$$, 'inline'),
  ('ec02e298-4625-4a36-8955-8a6504a0c5da', 'ae91f8c2-33c3-4cce-a7ba-7205d735b4c3', $$denivellering verlaagt consumentenvertrouwen; analyse met IS-MB-GA model$$,
   $$economie-vwo-2026-i-beleid-context2.png$$,
   $$Door de denivellering neemt het consumentenvertrouwen af, waardoor de bestedingen dalen. Een econoom analyseert dit met het IS-MB-GA model.$$, 'inline'),
  ('8a4da83f-03aa-4455-ad86-f27fd8a5f9de', 'ae91f8c2-33c3-4cce-a7ba-7205d735b4c3', $$figuur 3: IS-MB-GA model, met legenda$$,
   $$economie-vwo-2026-i-beleid-context3.png$$,
   $$Figuur 3 IS-MB-GA model
Bovenste grafiek: verticale as r (0 tot 7), horizontale as Y. Dalende lijnen IS₀ en IS₁ (IS₁ links van IS₀, pijl naar links); horizontale lijn MB₀ bij r = 3. IS₁ snijdt MB₀ bij Y₁, IS₀ snijdt MB₀ bij Y₀.
Onderste grafiek: verticale as π (0 tot 7), horizontale as Y. Stijgende lijn GA₀ (bij Y₀ ongeveer op π = 4).
Legenda:
Y = inkomen
r = reële rente in procenten
π = inflatie in procenten
Y₀ = Y*$$, 'inline'),
  ('909caec9-24a5-4299-911b-8a5a6a44d90c', 'ae91f8c2-33c3-4cce-a7ba-7205d735b4c3', $$IS-curve: dalend verband tussen reële rente en inkomen$$,
   $$economie-vwo-2026-i-beleid-context4.png$$,
   $$De IS-curve geeft het dalend verband weer tusen de reële rente en het inkomen.$$, 'inline'),
  ('1b32bcfc-28e5-45c9-ba27-e591ae0aec9f', 'ae91f8c2-33c3-4cce-a7ba-7205d735b4c3', $$periode 1: IS-curve verschuift naar IS₁; centrale bank brengt economie terug naar Y*$$,
   $$economie-vwo-2026-i-beleid-context5.png$$,
   $$In periode 1 verschuift de IS-curve naar IS₁. De econoom neemt aan dat de centrale bank met één rentestap de economie terugbrengt naar de potentiële productie (Y*).$$, 'inline'),
  ('078d1475-ec51-492f-af6a-143c01b5ceb9', 'ae91f8c2-33c3-4cce-a7ba-7205d735b4c3', $$financiering extra bestedingen: a hoger vlaktaktarief, b nieuwe staatsobligaties$$,
   $$economie-vwo-2026-i-beleid-context6.png$$,
   $$De econoom is van mening dat de overheid altijd de bestedingen moet verhogen in een situatie van onderbesteding. Deze extra bestedingen kunnen op twee manieren worden gefinancierd: a het verhogen van het tarief van de vlaktaks; b het uitgeven van nieuwe staatsobligaties.$$, 'inline'),
  ('1f5ccb0d-3ac1-4b84-bfe5-e58ad59076b3', 'ae91f8c2-33c3-4cce-a7ba-7205d735b4c3', $$onderbesteding bij lage inflatie en lage rente$$,
   $$economie-vwo-2026-i-beleid-context7.png$$,
   $$Er is sprake van onderbesteding. Daarom streeft de overheid naar een toename van het bbp. Ga uit van een situatie van een lage inflatie en een lage rente.$$, 'inline'),
  ('f4f9de5f-eb03-4e34-9498-7f8bd752fe65', '654a5b0c-143c-4b7a-a298-2a91b256724f', $$inleiding: houtkap in Zuid-Amerika; aannames over kaphout en eigendomsrechten$$,
   $$economie-vwo-2026-i-kappen-met-kappen-context1.png$$,
   $$In Zuid-Amerika verdwijnt door houtkap steeds meer tropisch regenwoud. Een econoom maakt een model en onderzoekt de houtkap voor een gedeelte van het tropisch regenwoud. De econoom gaat uit van een aantal aannames:
− Al het gekapte hout is van dezelfde kwaliteit en wordt grotendeels geëxporteerd naar de Verenigde Staten en Europa.
− Een werkend systeem van eigendomsrechten voor dit gedeelte van het tropische regenwoud ontbreekt.$$, 'inline'),
  ('6cc2d74d-7997-45a1-bc61-c9233176f7bd', '654a5b0c-143c-4b7a-a298-2a91b256724f', $$aanvullende aannames over de houthakkers$$,
   $$economie-vwo-2026-i-kappen-met-kappen-context2.png$$,
   $$De econoom voegt een aantal aannames over de houthakkers toe aan het model:
− De gemiddelde variabele kosten zijn voor alle houthakkers en per eenheid gekapt hout gelijk.
− Houthakkers ontvangen nu een marktprijs die hoger is dan de variabele kosten per eenheid product.
− Houthakkers hebben alleen de keuze om minder hout te kappen of meer hout te kappen.$$, 'inline'),
  ('715e7b3e-0f65-43c8-b7af-1ff41fb7d8b8', '654a5b0c-143c-4b7a-a298-2a91b256724f', $$conclusie econoom: dominante strategie en suboptimaal Nash-evenwicht$$,
   $$economie-vwo-2026-i-kappen-met-kappen-context3.png$$,
   $$De econoom concludeert: “Op basis van de aannames over de houthakkers, heeft iedere houthakker een dominante strategie waardoor op termijn een suboptimaal Nash-evenwicht ontstaat.”$$, 'inline'),
  ('2ff05af6-687b-41fc-9678-ae2d13dbf66c', '654a5b0c-143c-4b7a-a298-2a91b256724f', $$nieuw model: collectieve aanbodlijn met segmenten A₁ en A₂$$,
   $$economie-vwo-2026-i-kappen-met-kappen-context4.png$$,
   $$De econoom maakt een nieuw model (zie figuur 4). De econoom stelt een collectieve aanbodlijn op bestaande uit twee segmenten: A₁ en A₂.$$, 'inline'),
  ('a3053ad5-0f5d-4d96-a002-1083812320b7', '654a5b0c-143c-4b7a-a298-2a91b256724f', $$figuur 4: model kaphout in 2026, met vergelijkingen$$,
   $$economie-vwo-2026-i-kappen-met-kappen-context5.png$$,
   $$Figuur 4 Model kaphout in 2026
verticale as: gemiddelde opbrengst per m² in $ (0 tot 400); horizontale as: hoeveelheid kaphout als % van het tropisch regenwoud (0,0% tot 7,0%).
V: dalende lijn van 350 bij 0,0% naar 0 bij 7,0%.
A₁: horizontale lijn bij 100 van 0,0% tot 6,0%; A₂: verticale lijn bij 6,0% vanaf 100.
V: Qv = 7 – 0,02P | V = vraag kaphout als % van het tropisch regenwoud
A₁ → P = 100 | A = aanbod kaphout als % van het tropisch regenwoud
A₂ → Qa = 6% | bij (0% ≤ Q ≤ 6%)
P = De gemiddelde opbrengst van kaphout per m² tropisch regenwoud in $$$, 'inline'),
  ('b92b4628-0b55-49cb-b9f4-c5f7e152b886', '654a5b0c-143c-4b7a-a298-2a91b256724f', $$omvang en groei tropisch regenwoud; ga uit van marktevenwicht$$,
   $$economie-vwo-2026-i-kappen-met-kappen-context6.png$$,
   $$De totale omvang van het tropisch regenwoud is 700 miljoen hectare aan het begin van 2026. Het tropisch regenwoud zal zonder houtkap jaarlijks groeien met 2,2% per jaar. De werkelijke jaarlijkse verandering van het tropisch regenwoud in procentpunten is het groeipercentage minus het gekapte hout in procenten. Ga uit van het marktevenwicht.$$, 'inline'),
  ('2d83a7cd-b700-4767-9e4c-1c40cd36325a', '654a5b0c-143c-4b7a-a298-2a91b256724f', $$heffing op koop van hout: vraag wordt 1,8%$$,
   $$economie-vwo-2026-i-kappen-met-kappen-context7.png$$,
   $$De econoom wil de gevraagde hoeveelheid kaphout laten afnemen en stelt voor om een heffing te introduceren op de koop van hout. Hierdoor zal de vraag naar kaphout in het model 1,8% worden als percentage van het tropisch regenwoud.$$, 'inline'),
  ('650de46b-6fd4-45b6-bfe8-092d5af89cfb', '14c9e29f-2f02-47ce-bb1a-30d9350b10d5', $$inleiding: Australië exporteert delfstoffen; productie is zeer prijsinelastisch$$,
   $$economie-vwo-2026-i-australie-context1.png$$,
   $$Australië produceert en exporteert delfstoffen zoals steenkool en aardgas. De prijzen van deze delfstoffen worden op de wereldmarkt bepaald en hangen samen met de stand van de (gemiddelde) conjunctuur in de wereld. De productie van delfstoffen in Australië is zeer prijsinelastisch. Een econoom stelt: “Een hoogconjunctuur in de rest van de wereld heeft, via de prijselasticteit van de productie van delfstoffen, een zwak effect op de werkgelegenheid in de delfstoffenmarkt in Australië.”$$, 'inline'),
  ('9e57b59e-3f9c-4166-8d28-72ef5ad398be', '14c9e29f-2f02-47ce-bb1a-30d9350b10d5', $$in Australië is sprake van loonrigiditeit$$,
   $$economie-vwo-2026-i-australie-context2.png$$,
   $$In Australië is sprake van loonrigiditeit.$$, 'inline'),
  ('cb884a38-407d-42d1-bc32-54bb0915d946', '14c9e29f-2f02-47ce-bb1a-30d9350b10d5', $$kringloopmodel van de economie van Australië in 2023$$,
   $$economie-vwo-2026-i-australie-context3.png$$,
   $$Een econoom analyseert de economie van Australië in 2023 met behulp van een kringloopmodel (zie figuur 5). De pijlen zijn geldstromen.$$, 'inline'),
  ('bd3b35bd-36d3-4828-bca3-22f95c0e7703', '14c9e29f-2f02-47ce-bb1a-30d9350b10d5', $$figuur 5: kringloopmodel Australië (2023), met legenda$$,
   $$economie-vwo-2026-i-australie-context4.png$$,
   $$Figuur 5 Kringloopmodel Australië (2023)
Sectoren: gezinnen, banken, bedrijven, buitenland, overheid.
C = 1.237 (gezinnen → bedrijven); Y = 2.385 (bedrijven → gezinnen); B = 923 (gezinnen → overheid); O = 885 (overheid → bedrijven);
E = 671 (buitenland → bedrijven); M = 527 (bedrijven → buitenland);
4 = … (gezinnen → banken); 2 = … (banken → bedrijven); 1 = … (tussen buitenland en banken, richting onbekend); 3 = … (tussen banken en overheid, richting onbekend).
De getallen zijn in miljarden Australische dollars.
B = belastingen
C = particuliere consumptie
E = export van goederen en diensten
I = bedrijfsinvesteringen
M = import van goederen en diensten
O = overheidsbestedingen
S = particuliere besparingen
Y = nationaal inkomen
(vervangingsinvesteringen en afschrijvingen blijven buiten beschouwing)$$, 'inline'),
  ('0ca16a3e-a2eb-4eca-8099-e065a0f73346', '14c9e29f-2f02-47ce-bb1a-30d9350b10d5', $$richting pijlen 1 en 3 nog onbekend$$,
   $$economie-vwo-2026-i-australie-context5.png$$,
   $$In het kringloopmodel staan de pijlen tussen gezinnen, banken en bedrijven gegeven. De richting van de pijlen tussen buitenland, banken en overheid (pijlen 1 en 3) zijn nog onbekend.$$, 'inline'),
  ('801fde63-0edc-44f6-86d1-2c00ee823f13', '14c9e29f-2f02-47ce-bb1a-30d9350b10d5', $$Australië heeft in 2023 een positief saldo op de betalingsbalans$$,
   $$economie-vwo-2026-i-australie-context6.png$$,
   $$Australië heeft in 2023 een positief saldo op de betalingsbalans.$$, 'inline'),
  ('ebeffc16-01f6-40bb-b2ec-5fe812a2dded', 'fc02ff23-6f6f-4855-8cb3-bff261fcc493', $$inleiding: hypothecaire lening met woning als onderpand; DNB als toezichthouder$$,
   $$economie-vwo-2026-i-de-prijs-van-woningbezit-context1.png$$,
   $$In Nederland hebben veel huishoudens een woning gekocht met een hypothecaire lening. Dit is een leenvorm waarbij de woning als onderpand dient. De Nederlandsche Bank (DNB) is toezichthouder op de hypotheekmarkt en onderzoekt daarom de koopwoningmarkt (zie tabel 1).$$, 'inline'),
  ('26664bf0-2e10-453d-bd41-d86b35f58092', 'fc02ff23-6f6f-4855-8cb3-bff261fcc493', $$tabel 1: gegevens onderzoek Nederlandse koopwoningmarkt$$,
   $$economie-vwo-2026-i-de-prijs-van-woningbezit-context2.png$$,
   $$Tabel 1 Gegevens onderzoek Nederlandse koopwoningmarkt
| begin 2021 | eind 2022
hypotheekrente (looptijd 10 jaar) | 1,80% | 4,05%
inkomenstoets van DNB | 5,7 | 4,4
totale hypotheekschuld (in miljarden €) | € 740,1 | € 797,6
totale hypotheekschuld (in % van het bbp) | 93 | 83
| 2021 | 2022
reële groei bbp Nederland | 4,9% | 4,5%$$, 'inline'),
  ('6a61c827-f6c8-47f8-be46-18e2104452d8', 'fc02ff23-6f6f-4855-8cb3-bff261fcc493', $$inkomenstoets: maximale hypotheek als veelvoud van het primair inkomen$$,
   $$economie-vwo-2026-i-de-prijs-van-woningbezit-context3.png$$,
   $$De inkomenstoets is een eis van DNB. Een inkomenstoets van 5,7 betekent dat huishoudens een maximale hypotheek kunnen krijgen van 5,7 keer hun primair inkomen.$$, 'inline'),
  ('71df7b8d-1b50-4284-8f4a-a89f8f42c7fb', 'fc02ff23-6f6f-4855-8cb3-bff261fcc493', $$stelling: hogere hypotheekrente verhoogt wanbetalingsrisico; DNB verlaagt inkomenstoets$$,
   $$economie-vwo-2026-i-de-prijs-van-woningbezit-context4.png$$,
   $$Stelling: “Bij een hogere hypotheekrente stijgt het risico van wanbetaling. Hierdoor verlaagt DNB de inkomenstoets.”$$, 'inline'),
  ('e2ad8806-bf01-4478-b98d-4dd6d2312102', 'fc02ff23-6f6f-4855-8cb3-bff261fcc493', $$verplichte woonhuisverzekering bij hypothecaire lening$$,
   $$economie-vwo-2026-i-de-prijs-van-woningbezit-context5.png$$,
   $$Bij de aanschaf van een woning met een hypothecaire lening verplichten banken de huishoudens een woonhuisverzekering af te sluiten. Deze verzekering dekt onverwachte schade aan woningen, bijvoorbeeld waterschade als gevolg van stormen.$$, 'inline');

